"use strict";
const { esc, modal } = require("src/ui/dom.js");
const { describeItem } = require("src/runtime/item_catalog.js");
function openGM(doc, runtime, data, report) {
  const s = runtime.getSnapshot();
  if (!s) return;
  const R = data.rules(s.stat_data),
    el = modal(doc, "GM 控制台"),
