        ">" +
        esc(k) +
        "</label>",
    ).join("") +
    '</details><p class="xsd2-feedback" role="status"></p><button type="submit">应用修改</button><button type="button" data-cancel>撤回待执行行动</button></form><details><summary>人工覆盖 / 交还自动</summary>' +
    Object.entries(s.manual)
